#!/usr/bin/env node
/**
 * Generates the Delivery + Container Stalls screen data from the approved design.
 *
 *   node scripts/generate-ops-screens.mjs
 *
 * Reads design-reference/Selorg Admin Dashboard.dc.html, evaluates the design's own data
 * constants (SCREENS, LAYOUT, DETAIL, PURPOSE, ACTIONS, ACT_FORMS, BULK, ENTITY, CAP, META) and the
 * related-record map inside `linkedFor`, and writes typed TS data to src/modules/ops/data/. Re-run
 * whenever the design file changes — the generated files are not edited by hand.
 */
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const html = fs.readFileSync(path.join(root, "design-reference", "Selorg Admin Dashboard.dc.html"), "utf8");
const lines = html.split(/\r?\n/);

const start = lines.findIndex((l) => l.startsWith("const NAV = ["));
const end = lines.findIndex((l) => l.startsWith("class Component extends"));
if (start < 0 || end < 0) throw new Error("Couldn't locate the design data block");
const dataSrc = lines.slice(start, end).join("\n");
const NAMES = ["NAV", "META", "LAYOUT", "PURPOSE", "DETAIL", "ACTIONS", "ACT_FORMS", "BULK", "ENTITY", "CAP", "SCREENS"];
const D = new Function(`${dataSrc}\nreturn { ${NAMES.join(", ")} };`)();

/** Routes served by the ops engine, in sidebar order. */
const DELIVERY = ["deliveries", "bd-overview", "bd-queue", "bd-batches", "bd-stops", "bd-route", "bd-track", "bd-ops", "bd-exceptions", "vehicles"];
const STALLS = D.NAV.find((g) => g[0] === "Container Stalls")[1].map((i) => i[0]);
const ROUTES = [...DELIVERY, ...STALLS];

// Related-record links live inside the component's linkedFor() map: L("Label", c(i) [+ "sfx"] | "text", "route")
const linkStart = lines.findIndex((l) => /^\s+linkedFor\(r, rec, val\) \{/.test(l));
const linkLines = lines.slice(linkStart, linkStart + 90);
const LINKS = {};
for (const l of linkLines) {
  const m = l.match(/^\s+"?([\w-]+)"?: \[(L\(.*)\],?\s*$/);
  if (!m || !ROUTES.includes(m[1])) continue;
  LINKS[m[1]] = [...m[2].matchAll(/L\("([^"]+)",\s*(c\((\d+)\)(?:\s*\+\s*"([^"]*)")?|"([^"]*)"),\s*"([\w-]+)"\)/g)].map((x) =>
    x[3] !== undefined ? { label: x[1], col: Number(x[3]), suffix: x[4] ?? "", route: x[6] } : { label: x[1], text: x[5], route: x[6] }
  );
}

const COLOR = { "#d9534f": "var(--red-tx)", "#c78a1e": "var(--amber-tx)", "#3b7fc4": "var(--blue-tx)" };
const cell = (c) => (c && typeof c === "object" ? { label: String(c.v), tone: c.t } : String(c));
const flowOf = (r) => {
  const f = D.SCREENS[r].flow;
  return f ? f.map((s) => (Array.isArray(s) ? { label: s[0], actor: s[1] ?? "System" } : { label: s, actor: "System" })) : [];
};

const screens = {};
// Also used by the bulk Load Planning / Consignment Tracking screens (src/modules/ops/data/bulkScreens.ts),
// which exist in the frontend but not in the design's SCREENS map.
const usedActions = new Set(["Export view", "Match vehicle", "Assign driver", "Split into trips", "Dispatch load"]);
for (const r of ROUTES) {
  const s = D.SCREENS[r];
  if (!s) throw new Error(`Design has no SCREENS entry for ${r}`);
  (D.ACTIONS[r] ?? []).forEach((a) => usedActions.add(a));
  (D.BULK[r] ?? []).forEach((a) => usedActions.add(a.label));
  screens[r] = {
    id: r,
    group: D.META[r]?.[0] ?? "",
    // The sidebar label is what admins see everywhere else; META titles are breadcrumb variants.
    title: D.NAV.flatMap((g) => g[1]).find((i) => i[0] === r)?.[1] ?? D.META[r]?.[1] ?? r,
    hint: s.hint,
    flow: flowOf(r),
    flowAt: s.flowAt,
    kpis: s.kpis.map((k) => ({ value: k[0], label: k[1], ...(k[2] ? { color: COLOR[k[2]] ?? k[2] } : {}) })),
    tabs: s.tabs,
    columns: s.cols,
    rows: Object.fromEntries(Object.entries(s.rows).map(([tab, rows]) => [tab, rows.map((row) => row.map(cell))])),
    layout: D.LAYOUT[r] ?? "table",
    detail: D.DETAIL[r] ?? "generic",
    purpose: D.PURPOSE[r] ?? null,
    actions: D.ACTIONS[r] ?? [],
    bulk: (D.BULK[r] ?? []).map((b) => ({ label: b.label, ...(b.danger ? { danger: true } : {}), ...(b.only ? { only: b.only.source } : {}) })),
    entity: D.ENTITY[r] ?? "Record",
    cap: D.CAP[r] ?? "",
    links: LINKS[r] ?? [],
  };
}

const forms = {};
for (const a of [...usedActions].sort()) {
  const f = D.ACT_FORMS[a];
  if (!f) continue;
  forms[a] = {
    advances: !!f.adv,
    ...(f.effect ? { effect: f.effect } : {}),
    fields: f.fields.map((x) => ({ id: x.id, label: x.label, kind: x.kind, options: x.options, required: x.req })),
  };
}

const header = (what) =>
  `// GENERATED by scripts/generate-ops-screens.mjs from design-reference/Selorg Admin Dashboard.dc.html.\n// ${what} Do not edit by hand — re-run the generator.\n`;
const outDir = path.join(root, "src", "modules", "ops", "data");
fs.mkdirSync(outDir, { recursive: true });
fs.writeFileSync(
  path.join(outDir, "screens.generated.ts"),
  `${header("Screen definitions for the Delivery and Container Stalls modules.")}import type { OpsScreenDef } from "@/modules/ops/types";\n\nexport const GENERATED_SCREENS = ${JSON.stringify(screens, null, 2)} as unknown as Record<string, OpsScreenDef>;\n`
);
fs.writeFileSync(
  path.join(outDir, "actionForms.generated.ts"),
  `${header("Action dialogs (fields, whether the action advances the record's flow).")}import type { OpsActionForm } from "@/modules/ops/types";\n\nexport const GENERATED_ACTION_FORMS: Record<string, OpsActionForm> = ${JSON.stringify(forms, null, 2)};\n`
);
console.log(`Wrote ${Object.keys(screens).length} screens and ${Object.keys(forms).length} action forms to ${path.relative(root, outDir)}`);
console.log("Container Stalls routes:", STALLS.join(", "));
